#include <iostream>

long long power(long long a, long long b) {
    long long ans = 1;
    if (b == 0)
        return 1;
    while (b > 0) {
        if (b % 2 != 0)
            ans = ans * a;
        a = a * a;
        b = b / 2;
    }
    return ans;
}

